function journey(title, no, stageNames, touches, acts, emotions, pains, opps) {
 const row = (cls, vals, render) => `<div class="rr-jgrid"><div class="rr-jlabel"><b>${cls[0]}</b><span>${cls[1]}</span></div>${vals.map((v,i)=>render(v,i)).join('')}</div>`;
 return page(title,'USER JOURNEY · USER-JOURNEY-SKILL',no,`<div class="body-area"><div class="rr-journey">${row(['阶段','Stage'],stageNames,(v,i)=>`<div class="rr-jstage" style="--stage:${['#ef4444','#f59e0b','#3b82f6','#10b981','#8b5cf6'][i]}"><div class="no">0${i+1}</div><h3>${v}</h3><small>${['学习','实现','排查','优化','交付'][i]}</small></div>`)}${row(['触点','Touch'],touches,v=>`<div class="rr-jcell rr-jtouch">${v.map(x=>`<div>${x}</div>`).join('')}</div>`)}${row(['行为','Action'],acts,(v,i)=>`<div class="rr-jcell rr-jact"><div class="rr-mini"><i style="width:${65+i*5}%"></i><i style="width:${42+i*7}%"></i><i style="width:${84-i*6}%"></i></div><p>${v}</p></div>`)}${row(['情绪','Emotion'],emotions,(v,i)=>`<div class="rr-jcell rr-jemotion" style="--stage:${['#ef4444','#f59e0b','#3b82f6','#10b981','#8b5cf6'][i]};--y:${[44,66,72,56,35][i]}%"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><line x1="0" y1="50" x2="100" y2="50" stroke="#d9dee7" stroke-width=".8" stroke-dasharray="3 3"/><polyline points="0,${[36,49,63,70,48][i]} 50,${[44,66,72,56,35][i]} 100,${[58,72,65,42,30][i]}" fill="none" stroke="currentColor" stroke-width="1.6"/></svg><div class="dot"></div><div class="face">${['😐','😣','😤','😕','🙂'][i]}</div><div class="em">${v}</div></div>`)}${row(['痛点','Pain'],pains,v=>`<div class="rr-jcell rr-jpain">${v.map(x=>`<p>${x}</p>`).join('')}</div>`)}${row(['机会点','Opportunity'],opps,v=>`<div class="rr-jcell rr-jopp">${v.map(x=>`<p>${x}</p>`).join('')}</div>`)}</div></div>`);
}
