slides.push(page('机会优先级应同时看版本阻塞、覆盖面与可产品化程度','OPPORTUNITY MATRIX · §13',48,`<div class="body-area vc"><div class="rr-oppty"><div class="rr-quad"><h3>高影响 · 易启动</h3><span class="rr-sticky">统一文档入口与能力表</span><span class="rr-sticky">训练日志摘要与对象映射</span><p>优先建立共同知识与证据底座。</p></div><div class="rr-quad"><h3>高影响 · 需协同</h3><span class="rr-sticky">首次分叉定位</span><span class="rr-sticky">首个异常 rank</span><span class="rr-sticky">快速算子到生产演进</span><p>以 P0 场景牵引多团队闭环。</p></div><div class="rr-quad"><h3>局部提效 · 易交付</h3><span class="rr-sticky">增量构建</span><span class="rr-sticky">测试资产转换</span><span class="rr-sticky">IDE 约束提示</span><p>以工程基础能力降低高频重复操作。</p></div><div class="rr-quad"><h3>长期建设 · 平台化</h3><span class="rr-sticky">性能专家 Skill / Agent</span><span class="rr-sticky">A5 迁移与选型指导</span><span class="rr-sticky">跨框架训推适配</span><p>沉淀可审计的经验与生态能力。</p></div><div class="rr-axis-x">交付复杂度 / 协同成本 →</div><div class="rr-axis-y">业务影响 →</div></div></div>`));
slides.push(page('六项行动覆盖“知识—开发—定位—复用”的完整体验闭环','OPPORTUNITY PORTFOLIO · §17 PEER CARDS',49,`<div class="body-area"><div class="peer-wrap"><div class="peer-grid peer-many">${peerCard('tone-indigo','book','ACTION 01','统一、AI 可读的知识底座','文档入口、能力表、API 约束、示例和版本信息支持人和 Agent 稳定查询。')}${peerCard('tone-blue','wrench','ACTION 02','分层的快速算子开发路径','让 Triton-Ascend、PyPTO 支撑先导验证，并平滑演进至 Ascend C 生产实现。')}${peerCard('tone-teal','activity','ACTION 03','跨层故障、精度与性能诊断','打通日志、rank、框架、算子、图与代码位置，输出可移交的证据。')}${peerCard('tone-green','layers','ACTION 04','工程化与调试基本能力','增量构建、统一测试、IDE 提示、断点、内存与同步检测形成基础闭环。')}${peerCard('tone-pink','compass','ACTION 05','芯片与框架迁移指引','将 A5、编程范式、PyPTO 与训推分离的差异转为可检查的迁移路径。')}${peerCard('tone-purple','shield','ACTION 06','可验证的专家 Skill 与 Agent','工具同时给结论、依据和过程，使新手可复用，专家可复核和持续改进。')}</div></div></div>`));
