const start = html.indexOf('<div id="deck">');
const end = html.indexOf('</div>\n\n<!-- 调色面板', start);
if (start < 0 || end < 0) throw new Error('Deck markers not found');
const deckMarkup = slides.join('\n').replace(/__PAGE__/g, (_, offset, all) => {
  // The current section contains its own opening tag, so prior openings equal its 1-based page number.
  const pageNo = (all.slice(0, offset).match(/<section class="slide /g) || []).length;
  return String(pageNo).padStart(2, '0');
});
html = html.slice(0, start) + '<div id="deck">\n' + deckMarkup + '\n' + html.slice(end);
